-- Conference Tracker: starting conference list (53 records, compiled November 2026).
-- Run after 01_schema.sql. Safe to run again: existing records are updated in place, never deleted,
-- so everyone's saved statuses stay linked.

on conflict (id) do update set series=excluded.series, name=excluded.name, host=excluded.host, host_score=excluded.host_score, host_note=excluded.host_note, region=excluded.region, continent=excluded.continent, country=excluded.country, city=excluded.city, mode=excluded.mode, start_date=excluded.start_date, end_date=excluded.end_date, date_text=excluded.date_text, deadline=excluded.deadline, deadline_note=excluded.deadline_note, areas=excluded.areas, journals=excluded.journals, url=excluded.url, note=excluded.note, override=excluded.override, placeholder=excluded.placeholder;
